'use strict';
const CLIENT_VERSION = '1.4.0';
// All product records are persisted by the local server, never browser storage.
const S = {user:null,data:null,page:'overview',period:'latest',busy:false,error:'',modal:null,runtime:{mode:'offline',max_body_bytes:24*1024*1024},
  filter:{search:'',entity:'',kind:'',status:''}, assessment:null, reportEntity:'',import:{entity:'',start:'2026-09-01',end:'2026-10-01',files:{},validation:null},audit:null};
const $ = id => document.getElementById(id);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf = n => Number(n || 0).toLocaleString();
const attention = metrics => metrics?.attention_score == null ? 'N/A' : Number(metrics.attention_score).toLocaleString(undefined,{maximumFractionDigits:4});
const storedEngine = s => s.engine_version || s.metrics?.engine_version || 'Not recorded';
const fileCount = validation => `${validation.manifests.length}/${validation.schema_count??5}`;
const interval = s => `${s.period_start} inclusive → ${s.period_end} exclusive`;
const shortName = n => String(n).replace('SYNTHETIC · ','');
const date = s => s ? new Date(s).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}) : '—';
const time = s => s ? new Date(s).toLocaleString(undefined,{timeZone:'UTC'})+' UTC' : '—';
const paths = {
 overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 entities:'<path d="M4 21V5h10v16M14 11h6v10M2 21h20M7 8h4M7 12h4M7 16h4M17 14h1M17 17h1"/>',
 findings:'<path d="m12 3 10 18H2Z"/><path d="M12 9v5M12 17h.01"/>',
 review:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 12l2 2 4-5M9 18h6"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 14v6h16v-6"/>',
 reports:'<path d="M14 2H5v20h14V7ZM14 2v5h5M8 11h8M8 15h8M8 18h4"/>',
 shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',
 settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>',
 eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',
 plus:'<path d="M12 4v16M4 12h16"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 logout:'<path d="M9 4H4v16h5M10 12h11m-4-4 4 4-4 4"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
 activity:'<path d="M2 12h4l3-8 6 16 3-8h4"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
 database:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 4 18 4 18 0V5M3 12c0 4 18 4 18 0"/>'
};
const icon = name => `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${paths[name]||paths.reports}</svg>`;
const badge = (text,cls='') => `<span class="badge ${esc(cls)}">${esc(text)}</span>`;
const btn = (text,act,cls='',attrs='') => `<button class="${cls}" data-act="${act}" ${attrs}>${text}</button>`;
const writable = () => S.user && S.user.role !== 'reader';
const option = (val,label,current) => `<option value="${esc(val)}" ${String(val)===String(current)?'selected':''}>${esc(label)}</option>`;
const empty = (title,description,action='') => `<div class="empty">${icon('database')}<h2>${esc(title)}</h2><p>${esc(description)}</p>${action}</div>`;

async function api(path,body) {
  const headers={};
  if(body!==undefined){headers['Content-Type']='application/json';if(S.user)headers['X-CSRF-Token']=S.user.csrf;}
  const encoded=body===undefined?undefined:JSON.stringify(body);
  if(encoded&&new TextEncoder().encode(encoded).length>S.runtime.max_body_bytes)throw new Error(`This submission exceeds the ${S.runtime.max_body_bytes/1024/1024} MiB request limit. Split the exports into smaller periods or bundles.`);
  const response=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers,body:encoded,credentials:'same-origin'});
  const raw=await response.text();let data;
  try{data=JSON.parse(raw);}catch{throw new Error(response.status===413?'The hosting upload limit was exceeded. Use a smaller export bundle.':`The server returned an invalid response (HTTP ${response.status}). Check deployment configuration and retry.`);}
  if(!response.ok){const error=new Error(data.error||'Request failed');error.details=data.details;error.status=response.status;throw error;}
  return data;
}
function toast(message,error=false){const node=$('toast');node.textContent=message;node.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>{node.className='';},5500);}
async function refresh(){S.data=await api('/state');if(!S.import.entity&&S.data.entities.length)S.import.entity=S.data.entities[0].id;if(S.assessment)S.assessment=await api('/submissions/'+S.assessment.submission.id+'/assessment');}
async function openAssessmentResult(result){S.assessment=null;await refresh();S.period='assessment:'+result.id;S.assessment=await api('/submissions/'+result.id+'/assessment');S.page='assessment';S.filter={search:'',entity:S.assessment.submission.entity_id,kind:'',status:''};S.modal=null;window.scrollTo(0,0);}
async function operation(fn){if(S.busy)return;S.busy=true;render();try{await fn();}catch(error){if(error.status===401){S.user=null;S.modal=null;}toast(error.message,true);}finally{S.busy=false;render();}}
function submissions(){const all=S.data?.submissions||[];if(S.period.startsWith('assessment:'))return all.filter(s=>s.id===S.period.slice(11));if(S.period==='latest'){const seen=new Set();return all.filter(s=>{if(seen.has(s.entity_id))return false;seen.add(s.entity_id);return true;});}const seen=new Set();return all.filter(s=>{if(s.period_start.slice(0,7)!==S.period||seen.has(s.entity_id+'|'+s.period_start+'|'+s.period_end))return false;seen.add(s.entity_id+'|'+s.period_start+'|'+s.period_end);return true;});}
function scopedFindings(){const ids=new Set(submissions().map(s=>s.id));return (S.data?.findings||[]).filter(f=>ids.has(f.submission_id));}
function entityOptions(current,allLabel='All entities'){return option('',allLabel,current)+(S.data?.entities||[]).map(e=>option(e.id,shortName(e.name),current)).join('');}
function periodPicker(){const periods=[...new Set(S.data.submissions.map(s=>s.period_start.slice(0,7)))];const exact=S.period.startsWith('assessment:')?S.data.submissions.find(s=>s.id===S.period.slice(11)):null;return `<label class="period-label">Assessment scope<select id="period-select" aria-label="Assessment scope">${option('latest','Latest per entity',S.period)}${exact?option('assessment:'+exact.id,'This assessment · '+exact.id,S.period):''}${periods.map(p=>option(p,new Date(p+'-01T00:00:00Z').toLocaleDateString(undefined,{month:'long',year:'numeric',timeZone:'UTC'})+' · newest versions',S.period)).join('')}</select></label>`;}
function runtimeNotice(){return S.data.application_version===CLIENT_VERSION?'':`<div class="notice warning" role="alert">${icon('info')}<div><strong>Client and server release differ.</strong> This page uses application ${CLIENT_VERSION}; the server reports ${esc(S.data.application_version||'no application version (older server)')}. Restart the intended local source with the existing database, then reload this page. Stored assessments retain their original results.</div></div>`;}
function assessmentScope(s){return `<div class="assessment-context"><div><strong>Assessment ${esc(s.id)}</strong><p class="meta">Effective UTC interval: ${esc(interval(s))}</p><p class="meta">Created ${esc(time(s.created_at))} · ${nf(s.validation.row_count)} imported source records · ${fileCount(s.validation)} file types supplied</p></div><div class="version-stack"><span>Application <b>${esc(S.data.application_version||'Not reported')}</b></span><span>Running engine <b>${esc(S.data.engine_version)}</b></span><span>Stored assessment engine <b>${esc(storedEngine(s))}</b></span></div></div>`;}
function assessmentInputs(s){
 const drivers=s.supervisory.drivers, present=new Set(s.validation.manifests.map(m=>m.kind));
 const missing=Object.keys(S.data.schemas).filter(kind=>!present.has(kind));
 const unavailable=drivers.filter(d=>!d.assessed), zero=drivers.filter(d=>d.assessed&&!d.eligible);
 return panel('Assessment inputs & limitations','File presence, record eligibility and findings describe different things.',`<div class="panel-body input-summary"><h3>${nf(s.validation.row_count)} imported source records</h3><div class="counts">${s.validation.manifests.map(m=>`<span>${esc(m.kind)}: <strong>${nf(m.rows)}</strong></span>`).join('')}</div>${missing.length?`<div class="notice warning">${icon('info')}<div><strong>Optional exports not supplied: ${missing.map(kind=>esc(kind)+'.csv / JSON').join(', ')}.</strong><p>A missing file is not an explicitly empty complete export. Related checks cannot establish that expected evidence is absent.</p><ul>${missing.map(kind=>`<li>${esc(kind)}: ${drivers.filter(d=>d.missing_inputs.includes(kind)).map(d=>esc(d.name)).join('; ')||'No required check in this stored assessment.'}</li>`).join('')}</ul></div></div>`:''}<p>${unavailable.length} unavailable checks · ${zero.length} checks with zero eligible records. Detector details and denominators appear below.</p><p class="field-help">Approved automation and approved case exceptions are excluded from applicable closure, escalation, workflow and profile checks; repeated narratives exclude approved automation. Expectation rows can carry their own approved exception. Verify these controls against policy; an exclusion is not a finding.</p><p class="field-help">Alerts are assessed by creation time; closed cases by closure time and open cases by opening time. Supporting cross-period records remain available for linkage. Zero alerts alone does not establish missing monitoring.</p></div>`);
}
function populationDiagnostics(s){
 const d=s.diagnostics;if(!d)return '<p class="field-help">Population and relationship diagnostics were not reported by this server.</p>';
 return `<div class="table-wrap"><table><thead><tr><th>Dataset</th><th>Imported</th><th>In period</th><th>Out of period</th><th>Timestamp basis</th></tr></thead><tbody>${d.populations.map(p=>`<tr><td>${esc(p.kind)}</td><td>${nf(p.imported)}</td><td>${p.in_period===null?'Snapshot':nf(p.in_period)}</td><td>${p.out_of_period===null?'N/A':nf(p.out_of_period)}</td><td>${esc(p.basis)}</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><p class="field-help">${esc(d.period_note)} Escalation and workflow event counts describe timestamps; individual detectors may use these as supporting records under their own rules.</p><p><strong>${nf(d.approved_control_cases)} in-period cases carry approved automation or exception controls.</strong></p><p class="field-help">${esc(d.exclusion_note)}</p><h3 class="spaced">Source relationships</h3><p class="field-help">${esc(d.relationship_note)}</p>${d.relationships.length?`<ul>${d.relationships.map(r=>`<li><strong>${nf(r.affected_records)} ${esc(r.source)} records</strong> reference ${esc(r.target)} via ${esc(r.field)}: ${r.target_supplied?'referenced records absent from supplied export':'target export not supplied'}. <details><summary>Unresolved identifiers (up to 20)</summary><p class="mono break">${r.missing_ids.map(esc).join(', ')}</p></details></li>`).join('')}</ul>`:'<p class="field-help">No unresolved nonempty references were found in the submitted files. This does not establish export completeness.</p>'}</div>`;
}
function heading(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">Supervisory workbench</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function panel(title,description,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${action}</div>${body}</section>`;}
function stat(label,value,note,ico,color=''){return `<div class="stat"><div class="stat-top"><span>${label}</span>${icon(ico)}</div><div class="stat-value ${color}">${value}</div><small>${note}</small></div>`;}
function login(){return `<div class="login-page"><section class="login-story"><div class="brand"><img src="/favicon.svg" alt=""><div><strong>SENTRA AI</strong><small>CENTRALIZED SECURITY INTELLIGENCE</small></div></div><h1>Operational evidence.<br>Informed supervision.</h1><p>Assess SOC execution, identify missing evidence and focus examiner attention where it matters.</p><div class="principles"><div>${icon('shield')}${S.runtime.mode==='hosted'?'Secure hosted assessment workspace':'Local processing and offline operation'}</div><div>${icon('eye')}Traceable findings and human review</div><div>${icon('review')}Reproducible assessments and audit history</div></div></section><section class="login-form"><form class="login-box" id="login-form"><div class="eyebrow">${S.runtime.mode==='hosted'?'Secure workspace access':'Secure local access'}</div><h2>Sign in to the workbench</h2><p>${S.runtime.mode==='hosted'?'Use your SENTRA AI examiner account.':'Use the account created when the local server starts.'}</p><label>Username<input name="username" autocomplete="username" required value="examiner"></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label>${S.error?`<div class="error-text" role="alert">${esc(S.error)}</div>`:''}<button class="primary" type="submit">Sign in</button><p class="footnote">${S.runtime.mode==='hosted'?'Your deployment uses a private administrator password. Contact your administrator for access.':'Default demo login: examiner / SatSaDemo2026! An older database may need the reset-demo-password command.'}</p></form></section></div>`;}
function render(){
  const focus=document.activeElement?.id;const selection=document.activeElement?.selectionStart;
  const root=$('app');
  if(!S.user){root.innerHTML=login()+(S.busy?'<div class="loading-overlay"><div class="loading-box">Signing in…</div></div>':'');return;}
  if(!S.data){root.innerHTML='<div class="initial">Loading your assessments…</div>';return;}
  const names={overview:'Assessment overview',assessment:'Entity assessment',entities:'Entities',findings:'Findings',review:'Review queue',upload:'Submissions',reports:'Reports',methodology:'Methodology & audit'};
  const nav=[['overview','Overview'],['entities','Entities'],['findings','Findings'],['review','Review queue'],['upload','Submissions'],['reports','Reports'],['methodology','Methodology & audit']];
  const pending=scopedFindings().filter(f=>f.status==='pending').length;
  root.innerHTML=`<a class="skip-link" href="#main-content">Skip to content</a><div class="shell"><aside class="sidebar"><div class="brand"><img src="/favicon.svg" alt=""><div><strong>SENTRA AI</strong><small>CENTRALIZED SECURITY INTELLIGENCE</small></div></div><div class="nav-caption">Assessment workspace</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,title])=>btn(`${icon(id==='methodology'?'shield':id)}${title}${id==='review'&&pending?`<span class="count">${pending}</span>`:''}`,'nav',S.page===id?'active':'',`data-page="${id}" ${S.page===id?'aria-current="page"':''}`)).join('')}</nav><div class="side-bottom"><div class="offline">${icon('shield')}${S.runtime.mode==='hosted'?'Hosted workbench':'Offline workbench'}</div><p>${S.runtime.mode==='hosted'?'Persistent database':'Local data'} · Human judgement<br>Application ${esc(S.data.application_version||'Not reported')}<br>Running engine ${esc(S.data.engine_version)}</p></div></aside><main class="main" id="main-content"><header class="topbar"><div class="crumb"><span>Workspace</span><span>/</span><b>${names[S.page]}</b></div><div class="user"><span class="avatar">${esc(S.user.username.slice(0,2).toUpperCase())}</span><span>${esc(S.user.username)}<small class="role"> · ${esc(S.user.role)}</small></span>${btn(icon('logout'),'logout','quiet','aria-label="Sign out" title="Sign out"')}</div></header><div class="content">${runtimeNotice()}${({overview:overview,assessment:assessmentPage,entities:entitiesPage,findings:findingsPage,review:reviewPage,upload:uploadPage,reports:reportsPage,methodology:methodologyPage}[S.page])()}</div></main></div>${renderModal()}${S.busy?'<div class="loading-overlay" role="status"><div class="loading-box">Processing assessment…</div></div>':''}`;
  if(S.modal){const modal=$('modal');modal.showModal();modal.addEventListener('cancel',event=>{event.preventDefault();S.modal=null;render();});}
  if(focus&&$(focus)){try{$(focus).focus();if(typeof selection==='number')$(focus).setSelectionRange(selection,selection);}catch{}}
}

function overview(){
 const subs=submissions(), fs=scopedFindings(), high=fs.filter(f=>f.priority==='high'&&f.status!=='dismissed');
 const entitiesNeeding=new Set(fs.filter(f=>f.status==='pending'||f.status==='clarification').map(f=>f.entity_id)).size;
 const hasDemo=subs.some(s=>s.entity_name.startsWith('SYNTHETIC'));
 let html=heading('Assessment overview','Prioritise entities and review operational evidence across submitted SOC records.',periodPicker()+(writable()?btn(icon('upload')+' Import submission','nav','primary','data-page="upload"'):''));
 if(hasDemo)html+=`<div class="notice">${icon('info')}<div><strong>Synthetic demonstration workspace.</strong> All labelled entities are fictional. Signals support examiner review; they are not confirmed operational failures.</div></div>`;
 html+=`<div class="stats">${stat('Entities assessed',nf(subs.length),`${S.data.entities.length} registered entities`,'entities')}${stat('Require review',nf(entitiesNeeding),'Pending findings or clarification','eye','orange')}${stat('High-priority signals',nf(high.length),'Finding groups in selected assessments','findings','orange')}${stat('Alerts analysed',nf(subs.reduce((n,s)=>n+s.metrics.alerts,0)),'Created within the assessment periods','activity','accent')}</div>`;
 if(!subs.length)return html+panel('Begin an assessment','',empty('Your assessment workspace is ready','Register an entity and import SOC exports, or load synthetic demonstration data.',(S.user.role==='admin'?btn(icon('database')+' Load demo data','load-demo','primary'):'')+(writable()?btn('Import records','nav','','data-page="upload"'):'')));
 const ranked=[...subs].sort((a,b)=>(b.metrics.attention_score??-1)-(a.metrics.attention_score??-1));
 const rows=ranked.map(s=>{const f=fs.filter(f=>f.submission_id===s.id), pending=f.filter(f=>['pending','clarification'].includes(f.status)).length;return `<tr><td><div class="entity-name"><span class="entity-mark">${esc(shortName(s.entity_name).slice(0,2).toUpperCase())}</span><div><strong>${esc(shortName(s.entity_name))}</strong><span class="subline">${esc(s.sector)} · ${esc(s.size_band)}</span></div></div></td><td><div class="score"><strong>${attention(s.metrics)}</strong><div class="bar ${s.metrics.attention_score===0?'good':''}"><span style="--w:${s.metrics.attention_score||0}%"></span></div></div></td><td>${s.validation.completeness}%<span class="subline">${fileCount(s.validation)} file types</span></td><td>${s.supervisory?badge(s.supervisory.level,s.supervisory.level==='High'?'high':'kind')+'<br>':''}${badge(pending?`${pending} to review`:'No pending signals',pending?'pending':'low')}</td><td>${btn('Open assessment','assessment','quiet',`data-id="${esc(s.id)}"`)}</td></tr>`;}).join('');
 const ranking=panel('Entity review priorities','Attention index and submission completeness are separate measures.',`<div class="table-wrap"><table><thead><tr><th>Entity</th><th>Index / 100</th><th>Files supplied</th><th>Review status</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`,btn('All entities','nav','quiet heading-link','data-page="entities"'));
 const distribution=S.data.detectors.map(d=>({d,groups:fs.filter(f=>f.detector===d.id)})).filter(x=>x.groups.length);
 const max=Math.max(1,...distribution.map(x=>x.groups.reduce((n,f)=>n+f.affected_count,0)));
 const signals=panel('Where evidence needs attention','Affected records; overlap across detectors is possible.',`<div class="panel-body signals">${distribution.map(({d,groups})=>{let n=groups.reduce((v,f)=>v+f.affected_count,0);return `<div><div class="meter-line"><span>${esc(d.name)}</span><b>${nf(n)}</b></div><div class="signal-track"><span style="--w:${n/max*100}%;--color:${d.kind==='Negative space'?'#d29a43':'#198d83'}"></span></div></div>`;}).join('')||'<p class="muted">No supervisory signals in this selection.</p>'}</div>`);
 html+=`<div class="grid-main">${ranking}${signals}</div>`;
 const domains=['Detection','Investigation','Escalation','Response','Security operations','Governance','Operational discipline','Cyber resilience'];
 html+=panel('Capability evidence matrix','Affected/eligible percentage for assessable detectors. All eight capability areas show assessable evidence indicators, with missing populations explicit.',`<div class="table-wrap"><div class="heatmap"><span></span>${domains.map(d=>`<div class="heat-label">${d}</div>`).join('')}${ranked.map(s=>`<div class="heat-name">${esc(shortName(s.entity_name))}</div>${domains.map(d=>{const n=s.metrics.domains[d]??null;return `<div class="heat-cell" style="--cell:${n===null?'#edf1f5':n===0?'#d9eee8':n<10?'#f7edd2':n<35?'#f5d8a6':'#efb697'}" title="${esc(d)}: ${n===null?'not assessed':n+'% affected'}">${n===null?'N/A':n+'%'}</div>`;}).join('')}`).join('')}</div></div><div class="legend"><span><i style="--cell:#d9eee8"></i>No indicator</span><span><i style="--cell:#f7edd2"></i>&lt;10%</span><span><i style="--cell:#f5d8a6"></i>10–35%</span><span><i style="--cell:#efb697"></i>≥35%</span><span><i style="--cell:#edf1f5"></i>Not assessed</span></div>`);
 const latestGroups=[...fs].sort((a,b)=>(a.priority==='high'?0:1)-(b.priority==='high'?0:1)).slice(0,4);
 html+=`<div class="spaced">${trendPanel()}</div><div class="spaced">${panel('Review next','Open the evidence before recording a supervisory decision.',`<div class="panel-body finding-list">${latestGroups.map(f=>findingCard(f)).join('')||'<p class="muted">No findings to review.</p>'}</div>`,btn('Review queue','nav','quiet','data-page="review"'))}</div><p class="footnote">${esc(S.data.score_method)} Submission completeness reflects files supplied, not the completeness of their contents.</p>`;
 return html;
}
function findingsFilter(queue=false){
 const f=S.filter;return `<div class="filters"><input id="finding-search" type="search" placeholder="Search findings or entities" aria-label="Search findings" value="${esc(f.search)}"><select id="finding-entity" aria-label="Filter entity">${entityOptions(f.entity)}</select><select id="finding-kind" aria-label="Filter signal type">${option('','All signal types',f.kind)}${['Execution gap','Negative space'].map(k=>option(k,k,f.kind)).join('')}</select><select id="finding-status" aria-label="Filter review status">${option('',queue?'Needs review':'All review statuses',f.status)}${['pending','clarification','confirmed','dismissed'].map(k=>option(k,k[0].toUpperCase()+k.slice(1),f.status)).join('')}</select></div>`;
}
function filteredFindings(queue=false){const f=S.filter;return scopedFindings().filter(x=>(!f.entity||x.entity_id===f.entity)&&(!f.kind||x.kind===f.kind)&&(!f.status?(queue?['pending','clarification'].includes(x.status):true):x.status===f.status)&&(!f.search||(x.title+' '+x.entity_name+' '+x.summary).toLowerCase().includes(f.search.toLowerCase()))).sort((a,b)=>(a.priority==='high'?0:1)-(b.priority==='high'?0:1)||b.affected_count-a.affected_count);}
function findingCard(f){return `<article class="finding-card"><div><div class="tags">${badge(f.priority,f.priority)}${badge(f.kind,'kind')}${badge(f.status,f.status)}</div><h3>${esc(f.title)}</h3><p>${esc(f.summary)}</p><div class="foot"><span>${esc(shortName(f.entity_name))}</span><span>${nf(f.affected_count)} / ${nf(f.denominator)} ${esc(f.unit)}</span><span>${esc(f.domain)}</span><span>${esc(f.id)}</span></div></div>${btn(icon('eye')+' View evidence','finding','',`data-id="${esc(f.id)}"`)}</article>`;}
function findingScopeSummary(queue=false){
 const selected=submissions().filter(s=>!S.filter.entity||s.entity_id===S.filter.entity), visible=filteredFindings(queue);
 const total=scopedFindings().filter(f=>!S.filter.entity||f.entity_id===S.filter.entity).length;
 const unavailable=selected.reduce((n,s)=>n+(s.supervisory?.drivers||[]).filter(d=>!d.assessed).length,0);
 const noPopulation=selected.reduce((n,s)=>n+(s.supervisory?.drivers||[]).filter(d=>d.assessed&&!d.eligible).length,0);
 let message=`${visible.length} shown / ${total} stored finding groups in ${selected.length} selected assessment${selected.length===1?'':'s'}. ${unavailable} unavailable checks; ${noPopulation} checks with zero eligible records.`;
 const action=btn('Clear result filters','clear-filters','quiet');
 if(!selected.length)return empty('No assessments in this scope','The entity or assessment period excludes all available assessments. Choose another scope or clear the filters.',btn('Show latest assessments','reset-scope')+action);
 if(!visible.length&&total){const awaiting=queue&&!S.filter.search&&!S.filter.kind&&!S.filter.status;return `<p class="scope-summary">${esc(message)}</p>`+empty(awaiting?'No findings awaiting a decision':'Stored findings hidden by filters',awaiting?'Stored findings remain available with their decisions in Findings.':'Search, signal type or review status excludes stored findings in this assessment scope.',awaiting?btn('Show all review statuses','all-statuses'):action);}
 if(!visible.length)return `<p class="scope-summary">${esc(message)}</p>`+empty('Zero stored finding groups',`The selected assessments generated no finding groups. ${unavailable?unavailable+' checks were unavailable. ':''}${noPopulation?noPopulation+' checks had zero eligible records. ':''}Review the assessment inputs and eligible populations before interpreting this result.`,selected.length===1?btn('Inspect assessment inputs','assessment','',`data-id="${esc(selected[0].id)}"`):'');
 return `<div class="scope-summary split"><p>${esc(message)}${visible.length<total?' Other finding groups are hidden by the current result filters.':''}</p>${visible.length<total?action:''}</div>`;
}
function findingsPage(){const fs=filteredFindings();const selected=submissions().filter(s=>!S.filter.entity||s.entity_id===S.filter.entity);return heading('Supervisory findings','Inspect each signal, its rationale and the submitted evidence before reaching a conclusion.',periodPicker())+findingsFilter()+(selected.length===1?assessmentScope(selected[0]):'')+findingScopeSummary()+`<div class="finding-list">${fs.map(findingCard).join('')}</div>`;}
function reviewPage(){const fs=filteredFindings(true);const independent=panel('Check what the detectors missed','Independent examiner review of cases with no stored case, linked-alert or asset findings.',`<div class="panel-body"><p>Record concerns, request information or document no concern. Human concerns remain hypotheses until adjudicated.</p><div class="form-grid"><label>Assessment<select id="sample-submission">${submissions().map(s=>option(s.id,shortName(s.entity_name)+' · '+date(s.period_start),null)).join('')}</select></label><div class="actions">${btn('Open independent sample','sample','primary',!submissions().length?'disabled':'')}</div></div></div>`);const samplePlans=panel('Prioritised record samples','Open an assessment to see ranked cases, alerts and critical assets with selection reasons.',`<div class="panel-body queue-assessments">${submissions().filter(s=>!S.filter.entity||s.entity_id===S.filter.entity).map(s=>`<div class="split queue-plan"><div><strong>${esc(shortName(s.entity_name))}</strong><p class="meta">${esc(s.supervisory?.reason||'Review the assessment evidence.')}</p></div>${btn('Select records','assessment','',`data-id="${esc(s.id)}"`)}</div>`).join('')||'<p class="meta">No matching assessments.</p>'}</div>`);return heading('Examiner review queue','High-priority signals first. Include an unflagged case sample to check what the rules may have missed.',periodPicker())+findingsFilter(true)+independent+`<div class="spaced">${samplePlans}</div>`+`<h2 class="spaced queue-title">Finding groups awaiting a decision</h2>${findingScopeSummary(true)}<div class="finding-list">${fs.map(findingCard).join('')}</div>`;}
function entitiesPage(){
 const selected=new Map(submissions().map(s=>[s.entity_id,s]));
 return heading('Entity register','Assess organisations against their own configured policy and comparable peer context.',periodPicker()+(writable()?btn(icon('plus')+' Register entity','new-entity','primary'):''))+`<div class="entity-grid">${S.data.entities.map(e=>{const s=selected.get(e.id), fs=scopedFindings().filter(f=>f.entity_id===e.id);return `<article class="entity-card"><div class="split"><span class="entity-mark">${esc(shortName(e.name).slice(0,2).toUpperCase())}</span>${badge(s?'Assessed':'Awaiting submission',s?'low':'pending')}</div><h2>${esc(shortName(e.name))}</h2><p class="meta">${esc(e.sector)} · ${esc(e.size_band)} organisation${e.name.startsWith('SYNTHETIC')?' · Synthetic':''}</p><div class="score-row"><strong>${attention(s?.metrics)}</strong><span class="muted">/ 100 attention index</span></div><div class="metrics"><div><strong>${nf(s?.metrics.alerts)}</strong><small>Alerts in period</small></div><div><strong>${fs.length}</strong><small>Finding groups</small></div><div><strong>${s?s.validation.completeness+'%':'—'}</strong><small>Files supplied</small></div><div><strong>${s?date(s.period_start):'—'}</strong><small>Period starts</small></div></div><p class="peer">${esc(S.period==='latest'?e.peer_context:'Peer comparison shown for latest assessments only.')}</p><div class="actions">${s?btn('Open assessment','assessment','primary',`data-id="${esc(s.id)}"`):''}${btn('Findings','entity-findings','quiet',`data-id="${esc(e.id)}"`)}${writable()?btn(icon('settings')+' Policy','policy','quiet',`data-id="${esc(e.id)}"`):''}</div></article>`;}).join('')||empty('Register your first entity','Each entity has its own assessment policy.',writable()?btn('Register entity','new-entity','primary'):'')}</div>`;
}
const percent = n => n==null?'N/A':Number(n).toFixed(1)+'%';
function explanationView(x){return `<article class="explanation"><h3>${esc(x.record_id)}</h3><div class="expected"><b>Expected evidence</b><p>${esc(x.expected)}</p></div><div><b>Observed in this submission</b><ul>${x.observed.map(value=>`<li>${esc(value)}</li>`).join('')}</ul></div><div class="examiner-check"><b>Examiner check</b><p>${esc(x.examiner_check)}</p></div></article>`;}
function peerPanel(benchmark){
 const rows=benchmark.metrics.map(metric=>`<tr><td><strong>${esc(metric.name)}</strong><span class="subline">Affected / eligible</span></td><td>${percent(metric.entity_rate)}${metric.entity_rate!=null?`<div class="compare-track"><span style="--w:${metric.entity_rate}%"></span></div>`:''}</td><td>${percent(metric.peer_median)}${metric.peer_median!=null?`<div class="compare-track peer-track"><span style="--w:${metric.peer_median}%"></span></div>`:''}</td><td>${metric.difference_pp==null?'—':`${metric.difference_pp>0?'+':''}${metric.difference_pp.toFixed(1)} pp`}<span class="subline">${metric.eligible_peers} eligible peers</span></td></tr>`).join('');
 return panel('Peer benchmark','Same period and comparable submissions. Rates are signals for examination.',`<div class="panel-body"><div class="benchmark-head">${badge(`${benchmark.cohort_size} comparable peers`,benchmark.available?'low':'pending')}<p class="meta">${esc(benchmark.criteria)}</p></div>${!benchmark.available?`<div class="notice warning">${icon('info')}<div>Benchmark unavailable: at least ${benchmark.minimum_peers} other comparable entities are needed. Missing benchmarks are not treated as zero.</div></div>`:''}</div><div class="table-wrap"><table><thead><tr><th>Supervisory signal</th><th>This entity</th><th>Peer median</th><th>Difference</th></tr></thead><tbody>${rows}</tbody></table></div><div class="panel-body"><p class="meta">Cohort: ${benchmark.peers.map(p=>esc(shortName(p.entity_name))).join(', ')||'No matching peers.'}</p><p class="footnote">${esc(benchmark.limitation)}</p></div>`);
}
function selectionCards(selection,submission){return selection.records.map(item=>`<article class="selected-record"><div class="sample-rank">${item.rank}</div><div class="sample-main"><div class="tags">${badge(item.kind==='cases'?'Case':item.kind==='assets'?'Asset':'Alert','kind')}${badge(item.severity,item.severity==='critical'?'high':'')}${badge(`${item.signals.length} signal${item.signals.length===1?'':'s'}`)}</div><h3 class="mono">${esc(item.record_id)}</h3><p>${esc(item.selection_reason)}</p><p class="meta">${item.signals.map(signal=>esc(signal.title)).join(' · ')}</p><details class="selection-detail"><summary>Why selected · ${item.score} review points</summary><p class="field-help">Severity ${item.score_breakdown.severity} + signal priority ${item.score_breakdown.highest_signal_priority} + additional detectors ${item.score_breakdown.additional_detectors}. Points are a selection heuristic, not a risk score.</p><p class="mono">Asset: ${esc(item.asset_id||'Not supplied')}</p></details></div>${btn('Open record & explanation','open-record','',`data-submission="${esc(submission)}" data-kind="${esc(item.kind)}" data-id="${esc(item.record_id)}"`)}</article>`).join('')||empty('No unreviewed flagged records','Known findings may already have decisions, or no rule signals were generated. Include an independent case sample.');}
function aiPanel(s){
 const ai=s.metrics.ai_analysis;
 if(!ai)return panel('AI anomaly exploration','Isolation Forest',`<div class="panel-body"><p>This historical assessment predates the AI model. Use Re-analyse stored files to create a new assessment.</p></div>`);
 const records=(ai.candidates||[]).map(c=>`<tr><td><strong class="mono">${esc(c.case_id)}</strong><span class="subline">${esc(c.severity)}</span></td><td>${esc(c.decision_score)}<span class="subline">Threshold: below 0</span></td><td>${c.features.map(f=>`<div><strong>${esc(f.feature.replaceAll('_',' '))}</strong>: ${esc(f.observed)}; cohort median ${esc(f.cohort_median)}; score change at median ${esc(f.score_change_at_median)}</div>`).join('')}</td><td>${btn('Open source evidence','open-record','quiet',`data-submission="${esc(s.id)}" data-kind="cases" data-id="${esc(c.case_id)}"`)}</td></tr>`).join('');
 return panel('AI anomaly exploration','Locally trained Isolation Forest; exploratory candidates remain separate from rule findings and the attention index.',`<div class="panel-body"><p><strong>${nf(ai.flagged_count)} unusual records</strong> · ${nf(ai.trained_cohorts||0)} trained severity cohorts · ${esc(ai.status.replaceAll('_',' '))}</p><p class="field-help">${esc(ai.reason||ai.training)}</p><p class="field-help">${esc(ai.explanation)}</p><p class="field-help">${esc(ai.limitation)}</p><details class="spaced"><summary>Model provenance and training cohorts</summary><p class="mono">${esc(ai.model)} v${esc(ai.model_version)} · Scikit-Learn ${esc(ai.sklearn_version||'unavailable')} · seed ${esc(ai.parameters.random_state)} · ${esc(ai.parameters.n_estimators)} trees</p>${(ai.cohorts||[]).map(c=>`<p class="meta break">${esc(c.severity)}: ${nf(c.records)} records; ${esc(c.status)}. ${esc(c.reason||'Training SHA-256: '+c.training_sha256)}</p>`).join('')}</details></div>${records?`<div class="table-wrap"><table><thead><tr><th>Case</th><th>Model decision score</th><th>Feature sensitivity explanation</th><th>Evidence</th></tr></thead><tbody>${records}</tbody></table></div>`:''}`);
}
function assessmentPage(){
 const data=S.assessment;if(!data)return heading('Entity assessment','Choose a completed assessment from Overview or Submissions.')+empty('Select an assessment','Open an entity assessment to inspect its evidence.',btn('Back to overview','nav','','data-page="overview"'));
 const s=data.submission, summary=s.supervisory, selection=data.selection, findings=data.findings;
 const active=findings.filter(f=>f.status!=='dismissed');
 const execution=findings.filter(f=>f.kind==='Execution gap'), negative=findings.filter(f=>f.kind==='Negative space');
 const positive=s.peer_benchmark.metrics.filter(m=>m.difference_pp>0).sort((a,b)=>b.difference_pp-a.difference_pp);
 const workflow=['Submission validated','Signals assessed','Peer context','Review prioritised','Evidence explained'];
 let html=heading(esc(shortName(s.entity_name)),`${esc(s.sector)} · ${esc(s.size_band)} · ${date(s.period_start)} to ${date(s.period_end)} (end exclusive)`,btn('Overview','nav','quiet','data-page="overview"')+btn('Findings for this assessment','assessment-findings')+(writable()?btn('Re-analyse stored files','reanalyse'):'')+btn(icon('download')+' Export assessment','report','',`data-format="html" data-submission="${esc(s.id)}"`));
 html+=assessmentScope(s);
 html+=`<div class="spaced">${aiPanel(s)}</div>`;
 if(storedEngine(s)!==S.data.engine_version)html+=`<div class="notice warning">${icon('clock')}<div><strong>Historical engine results preserved.</strong> This assessment used engine ${esc(storedEngine(s))}; the running engine is ${esc(S.data.engine_version)}. Use Re-analyse stored files to create a new traceable assessment with the current engine.</div></div>`;
 html+=`<ol class="assessment-flow" aria-label="Assessment workflow">${workflow.map((label,i)=>`<li><span>${i+1}</span>${label}</li>`).join('')}</ol><section class="assessment-hero"><div><div class="eyebrow">Supervisory review attention</div><h2>${badge(summary.level,summary.level==='High'?'high':'kind')}<span>${attention(s.metrics)}<small>/100 index</small></span></h2><p>${esc(summary.reason)}</p><p class="field-help">${esc(summary.level_method)}</p><p class="field-help"><strong>${findings.length} stored finding groups</strong> · ${summary.unreviewed_groups} awaiting review. Finding count, review attention and index are separate measures.</p>${s.metrics.attention_score===0&&findings.length?'<p class="rounding-note">The stored historical index rounded to 0. Finding groups are still present; an index of 0 does not mean zero findings.</p>':''}</div><div class="hero-action">${btn(icon('review')+` Review ${selection.selected_count} selected records`,'recommended','primary',selection.selected_count?'':'disabled')}<p class="meta">${selection.population} unique unreviewed candidates<br>${selection.covered_detectors.length} detector types represented</p></div></section>`;
 if(s.entity_name.startsWith('SYNTHETIC'))html+=`<div class="notice">${icon('info')}<div>Synthetic entity and records. These findings demonstrate the workflow; they do not establish real-world accuracy.</div></div>`;
 html+=`<div class="stats">${stat('Execution gaps',nf(active.filter(f=>f.kind==='Execution gap').length),'Non-dismissed finding groups','findings','orange')}${stat('Negative space',nf(active.filter(f=>f.kind==='Negative space').length),'Missing expected submitted evidence','database','orange')}${stat('Peer context',nf(s.peer_benchmark.cohort_size),'Matching other entities','entities')}${stat('Evidence inputs',s.validation.completeness+'%',`${fileCount(s.validation)} supported file types supplied`,'shield','accent')}</div>`;
 if(positive.length)html+=`<div class="notice warning">${icon('activity')}<div><strong>Largest observed peer difference:</strong> ${esc(positive[0].name)} is ${percent(positive[0].entity_rate)} affected here versus ${percent(positive[0].peer_median)} peer median (+${positive[0].difference_pp.toFixed(1)} percentage points). This comparison is contextual, not a confirmed weakness.</div></div>`;
 const signalPanel=(title,list,kind)=>panel(title,kind==='Negative space'?'Expected evidence missing from the submitted records.':'Operational execution inconsistent with the configured checks.',`<div class="panel-body finding-list">${list.map(findingCard).join('')||'<p class="muted">No finding groups. Check the assessment coverage below before interpreting this as effective operation.</p>'}</div>`);
 html+=`<div class="spaced">${assessmentInputs(s)}</div><div class="supervisory-columns spaced">${signalPanel('Execution gaps',execution,'Execution gap')}${signalPanel('Negative space',negative,'Negative space')}</div><div class="spaced">${peerPanel(s.peer_benchmark)}</div>`;
 const rows=summary.drivers.map(driver=>`<tr><td><strong>${esc(driver.name)}</strong><span class="subline">${esc(driver.kind)}</span></td><td>${driver.assessed?driver.eligible?badge(driver.affected?'Findings present':'Zero affected records','low'):badge('No eligible records','kind'):badge('Unavailable check','pending')}<span class="subline">${driver.missing_inputs.length?'Missing: '+driver.missing_inputs.map(esc).join(', '):esc(driver.assessment_note||'')}</span></td><td>${driver.assessed?`${nf(driver.affected)} / ${nf(driver.eligible)}`:'—'}</td><td>${percent(driver.rate)}<span class="subline">${driver.included_in_index?'Included in mean':'Excluded from mean'}</span></td><td>${driver.finding_ids.map(id=>btn('Explain','finding','quiet',`data-id="${esc(id)}"`)).join('')||'—'}</td></tr>`).join('');
 html+=`<div class="spaced">${panel('Why this attention index?','Every detector contribution and missing capability is visible.',`<div class="panel-body"><p>${esc(summary.method)}</p><p class="field-help">${summary.index_terms} eligible detector rates contribute to the stored ${attention(s.metrics)} index. ${summary.missing_capabilities.length?'Not assessed: '+summary.missing_capabilities.map(esc).join(', '):'All configured detector inputs were supplied.'}</p></div><div class="table-wrap"><table><thead><tr><th>Detector</th><th>Evidence coverage</th><th>Affected / eligible</th><th>Contribution</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`)}</div>`;
 const independent=S.assessment.independent_sample, activity=S.assessment.activity_context;
 html+=`<div class="spaced">${panel('Check what the detectors missed','Independent examination is part of supervisory assurance.',`<div class="panel-body"><p>${esc(independent.purpose)}</p><p class="meta">${nf(independent.population)} eligible unflagged cases; ${nf(independent.excluded_cases)} excluded by direct or linked stored findings. ${independent.records.length} reproducible cases selected.</p>${btn('Open independent sample','assessment-sample','primary')}</div>`)}</div>`;
 if(activity?.available)html+=`<div class="notice ${activity.attention?'warning':''} spaced">${icon('activity')}<div><strong>Prior-period activity context:</strong> ${activity.current_daily_rate} alerts/day versus ${activity.previous_daily_rate} previously; change ${activity.change_percent===null?'unavailable':activity.change_percent+'%'}. ${esc(activity.reason)}<p class="field-help">${esc(activity.limitation)}</p></div></div>`;
 html+=`<div class="spaced">${panel('Expert review comparison','Evaluate independently adjudicated held-out labels.',`<div class="panel-body"><p class="meta">Download the blinded review package and have experts assess its records independently. Upload completed labels to calculate precision, recall and review yield against a seeded baseline. Synthetic labels do not establish real-world effectiveness.</p>${btn('Download blinded review package','blind-review','','data-submission="'+esc(s.id)+'"')}${writable()?'<label class="spaced">Adjudicated labels (CSV or JSON)<input id="expert-label-file" type="file" accept=".csv,.json"></label>':''}</div>`)}</div>`;
 html+=`<div class="spaced" id="recommended-records">${panel('Recommended examiner sample','Known signals, transparent ranking and detector coverage.',`<div class="panel-body"><p class="meta">${esc(selection.method)}</p><div class="selected-list">${selectionCards(selection,s.id)}</div><p class="footnote">${esc(selection.limitation)}</p></div>`,btn('Open selected sample','recommended','quiet',selection.selected_count?'':'disabled'))}</div>`;
 html+=`<div class="spaced">${panel('Submission traceability','Preserved source, policy and validation notes.',`<div class="panel-body"><p class="mono">${esc(s.id)} · SHA-256 ${esc(s.checksum)}</p><div class="actions spaced">${btn('Source manifests & policy','submission','',`data-id="${esc(s.id)}"`)}${btn('Independent case sample','assessment-sample')}</div><details class="record spaced"><summary>Validation observations (${s.validation.issues.length})</summary><div class="record-body">${s.validation.issues.map(issue=>`<p class="meta">${esc(issue.level)} · ${esc(issue.file)} · ${esc(issue.message)}</p>`).join('')||'<p class="meta">No structural validation issues. Export completeness still requires confirmation.</p>'}</div></details></div>`)}</div>`;
 return html;
}
function fileHeaders(content,filename){if(filename.toLowerCase().endsWith('.json')){const data=JSON.parse(content);const rows=Array.isArray(data)?data:data.records;return rows?.[0]?Object.keys(rows[0]):[];}let i=0,quoted=false,cell='',headers=[];for(const c of content.replace(/^\uFEFF/,'')){i++;if(c==='"'){quoted=!quoted;continue;}if(c===','&&!quoted){headers.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){headers.push(cell);break;}else cell+=c;if(i>10000)break;}return headers.length?headers.map(h=>h.trim()):[cell.trim()];}
function uploadPage(){
 const im=S.import, val=im.validation;
 const files=Object.entries(S.data.schemas).map(([kind,schema])=>{const f=im.files[kind],fields=[...schema.required,...schema.optional];return `<div class="file-card ${f?'has-file':''}" data-drop="${kind}"><div class="row"><h3>${kind[0].toUpperCase()+kind.slice(1)}</h3>${f?btn(icon('close'),'remove-file','quiet',`data-kind="${kind}" aria-label="Remove ${kind} file"`):badge(kind==='alerts'?'Required':'Optional')}</div><label class="meta" for="file-${kind}">Choose CSV or JSON, or drop a file here.</label><input id="file-${kind}" data-file="${kind}" type="file" accept=".csv,.json" ${!writable()?'disabled':''}>${f?`<p class="meta break">${esc(f.filename)} · ${nf(f.content.length)} characters</p><details><summary>Map source columns</summary><div class="mapping">${fields.map(field=>`<label>${esc(field)}${schema.required.includes(field)?' *':''}<select data-map-kind="${kind}" data-map-field="${field}" aria-label="${kind} ${field} source column">${option('','Automatic mapping',f.mapping?.[field]||'')}${(f.headers||[]).map(h=>option(h,h,f.mapping?.[field])).join('')}</select></label>`).join('')}</div></details>`:''}<a class="heading-link" href="/api/templates/${kind}.csv" download>Download CSV template</a></div>`;}).join('');
 return heading('Import SOC submissions','Upload periodic exports. Validation identifies data issues before analytics run.',S.user.role==='admin'?btn(icon('database')+' Load demo data','load-demo'): '')+`<div class="upload-layout"><div><section class="panel"><div class="panel-body"><div class="step"><h2><span class="step-number">1</span>Entity and assessment period</h2><div class="form-grid"><label>Entity<select id="import-entity">${entityOptions(im.entity,'Select entity')}</select></label><div class="actions">${writable()?btn(icon('plus')+' Register entity','new-entity'):''}</div><label>Period start (UTC)<input id="import-start" type="date" value="${esc(im.start)}"></label><label>Period end, exclusive (UTC)<input id="import-end" type="date" value="${esc(im.end)}"></label></div><p class="field-help">For September, use 1 September to 1 October. Cross-period cases can be included for linkage.</p></div><div class="step"><h2><span class="step-number">2</span>Attach and map exports</h2><div class="file-grid"><div class="notice"><div><strong>Periodic export bundle</strong><p class="meta">Load a periodic bundle converted from a database export or an internal API snapshot. Validate the bundle before analysis.</p><input id="bundle-file" type="file" accept=".json" aria-label="Load periodic export bundle"></div></div>${files}</div></div><div class="step"><h2><span class="step-number">3</span>Validate and assess</h2>${val?`<div class="notice ${val.valid?'success':'warning'}">${icon(val.valid?'check':'findings')}<div><strong>${val.valid?'Validation passed':'Validation needs correction'}</strong><p>${nf(val.row_count)} records · ${val.completeness??0}% of file types supplied</p></div></div><div class="issue-list">${val.issues.map(i=>`<div class="issue ${i.level}"><b>${esc(i.level.toUpperCase())} · ${esc(i.file)}${i.row?' · row '+i.row:''}</b><br>${esc(i.message)}</div>`).join('')||'<p class="meta">No structural issues detected. Source export completeness still needs examiner confirmation.</p>'}</div>`:'<p class="muted">Validation checks columns, identifiers, dates, statuses and impossible timelines.</p>'}<div class="button-row">${btn('Validate files','validate','',!Object.keys(im.files).length||!writable()?'disabled':'')}${btn('Run assessment','run-assessment','primary',!val?.valid||!im.entity||!writable()?'disabled':'')}</div></div></div></section><div class="spaced">${submissionHistory()}</div></div><aside class="panel upload-help"><div class="panel-body"><h2>Submission guidance</h2><ul class="checklist"><li>${icon('check')}Include stable record IDs to link alerts, cases and escalations.</li><li>${icon('check')}Use ISO 8601 dates with UTC or explicit timezone offsets.</li><li>${icon('check')}Missing files are marked not assessed, rather than assumed healthy.</li><li>${icon('check')}Coverage findings require asset inventory and source coverage evidence.</li><li>${icon('shield')}${S.runtime.mode==='hosted'?'Assessments and examiner decisions are stored in your connected database.':'Processing and storage remain on the local server.'}</li></ul><p class="meta">Prototype limits: 100,000 rows per file and ${Math.floor(S.runtime.max_body_bytes/(1024*1024))} MiB per request (including JSON encoding). CSV and JSON exports are supported.</p></div></aside></div>`;
}
function submissionHistory(){return panel('Assessment history','Original submission checksums and policy snapshots are preserved.',S.data.submissions.length?`<div class="table-wrap"><table><thead><tr><th>Entity / period</th><th>Records</th><th>Files</th><th>Created by</th><th></th></tr></thead><tbody>${S.data.submissions.map(s=>`<tr><td><strong>${esc(shortName(s.entity_name))}</strong><span class="subline">${date(s.period_start)} – ${date(s.period_end)} (exclusive)</span></td><td>${nf(s.validation.row_count)}</td><td>${fileCount(s.validation)}</td><td>${esc(s.actor)}</td><td>${btn('Assessment','assessment','quiet',`data-id="${esc(s.id)}"`)}${btn('Provenance','submission','quiet',`data-id="${esc(s.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No submissions yet','Completed assessments will appear here.'));}
function reportsPage(){return heading('Assessment reports','Export evidence, examiner decisions and assessment limitations for supervisory follow-up.')+`<section class="panel"><div class="panel-body"><div class="form-grid"><label>Report scope<select id="report-entity">${entityOptions(S.reportEntity,'All entities · latest assessments')}</select></label><div><h3>Latest assessed period per entity</h3><p class="field-help">Use assessment history to export a specific earlier submission.</p></div></div></div></section><div class="report-grid">${[['html','Printable report','Evidence IDs, rationale, decisions and limitations. Open the downloaded file and use Print to save as PDF.'],['csv','Findings spreadsheet','One row per finding with affected counts, review status and supporting record identifiers.'],['json','Complete assessment export','Structured metrics, policy snapshots, source manifests, review history and evidence identifiers.']].map(([format,title,desc])=>`<article class="report-card">${icon('reports')}<h2>${title}</h2><p>${desc}</p>${btn(icon('download')+' Download '+format.toUpperCase(),'report','',`data-format="${format}"`)}</article>`).join('')}</div>${panel('Auditability','Each import and review action is recorded in a hash-linked history.',`<div class="panel-body"><div class="notice ${S.data.audit.valid?'success':'warning'}">${icon('shield')}<div><strong>${S.data.audit.valid?'Audit chain verified':'Audit integrity requires attention'}</strong><p>${S.data.audit.checked} records checked. This is tamper-evident within the local database, not tamper-proof against a privileged database owner.</p></div></div>${btn('Inspect audit history','audit')}</div>`)}`;}
function methodologyPage(){return heading('Methodology & audit','Transparent rules, preserved policy snapshots and human review throughout the assessment.')+`<div class="notice">${icon('info')}<div><strong>Decision support, not an automated verdict.</strong> Confirm findings against source completeness, approved procedures and legitimate exceptions.</div></div><div class="grid-main"><div class="method-list">${S.data.detectors.map(d=>`<article class="method"><div class="tags">${badge(d.kind,'kind')}${badge(d.domain)}</div><h2>${esc(d.name)}</h2><p>${esc(d.description)}</p><p class="mono">${esc(d.id)} · v${esc(S.data.engine_version)}</p></article>`).join('')}</div><div><section class="panel"><div class="panel-head"><h2>Attention index</h2></div><div class="panel-body"><p>${esc(S.data.score_method)}</p><p class="footnote">The index uses transparent, equally weighted rule rates. Weights and thresholds have not been calibrated on real SOC data. It is unsuitable as a standalone national ranking.</p></div></section><section class="panel spaced"><div class="panel-head"><h2>Peer comparison</h2></div><div class="panel-body"><p class="muted">Peers must share the exact reporting period, sector, size band, supplied file types and preserved policy. At least two other entities are required.</p><p class="footnote">Similar file completeness does not guarantee equivalent coverage or reporting quality. Comparisons remain contextual indicators.</p></div></section><section class="panel spaced"><div class="panel-head"><h2>Accounts & audit</h2></div><div class="panel-body"><div class="actions">${btn('View audit history','audit')}${S.user.role==='admin'?btn('Create account','new-user'):''}</div><p class="footnote">Examiners can import and review. Readers can inspect and export. Administrators can create accounts and load demo data.</p></div></section></div></div>`;}

function trendPanel(){
 const periods=[...new Set(S.data.submissions.map(s=>s.period_start.slice(0,7)))].sort().slice(-12);
 if(periods.length<2)return panel('Attention index over time','At least two reporting periods are needed.',empty('Trend not yet available','Import another period to compare supervisory signals over time.'));
 const entities=S.data.entities.filter(e=>S.data.submissions.some(s=>s.entity_id===e.id)).slice(0,6);
 const colors=['#b26b20','#158574','#456caa','#7a54a0','#9c4c6d','#426d61'];
 const snapshots=entities.map(e=>periods.map(p=>S.data.submissions.find(s=>s.entity_id===e.id&&s.period_start.slice(0,7)===p)));
 const max=Math.max(20,...snapshots.flat().filter(Boolean).map(s=>s.metrics.attention_score||0));
 const ceiling=Math.ceil(max/10)*10,x=i=>46+i*640/(periods.length-1),y=v=>150-v/ceiling*126;
 let chart=`<svg class="chart" viewBox="0 0 720 190" role="img" aria-label="Attention index trend by entity and reporting period">${[0,ceiling/2,ceiling].map(n=>`<line class="grid" x1="46" x2="686" y1="${y(n)}" y2="${y(n)}"/><text x="5" y="${y(n)+4}">${n}</text>`).join('')}${periods.map((p,i)=>`<text x="${x(i)}" y="178" text-anchor="middle">${esc(p)}</text>`).join('')}`;
 snapshots.forEach((series,j)=>{let path='',previous=-2;series.forEach((s,i)=>{if(s?.metrics.attention_score!=null){path+=(previous===i-1?' L':' M')+x(i)+' '+y(s.metrics.attention_score);previous=i;}});chart+=`<path d="${path}" fill="none" stroke="${colors[j]}" stroke-width="2.5"/>`;series.forEach((s,i)=>{if(s?.metrics.attention_score!=null)chart+=`<circle cx="${x(i)}" cy="${y(s.metrics.attention_score)}" r="4" fill="${colors[j]}"><title>${esc(shortName(s.entity_name))}: ${s.metrics.attention_score} in ${esc(periods[i])}; ${s.validation.completeness}% file completeness</title></circle>`;});});
 chart+='</svg>';
 return panel('Attention index over time','Historical assessment snapshots; review changes in policy and completeness before interpreting trends.',`<div class="panel-body">${chart}<div class="legend-text">${entities.map((e,i)=>`<span style="color:${colors[i]}">● ${esc(shortName(e.name))}</span>`).join('')}</div><p class="footnote">Shows up to six entities and the last twelve reporting months. A missing index leaves a gap; it is not treated as zero.</p></div>`);
}
function recordsView(records,kind){const id={cases:'case_id',alerts:'alert_id',assets:'asset_id',escalations:'escalation_id',workflow:'event_id',expectations:'expectation_id'}[kind]||'asset_id';return records.map((r,i)=>`<details class="record" ${i===0?'open':''}><summary><strong>${esc(r[id]||'Record')}</strong>${r.severity?badge(r.severity,r.severity==='critical'?'high':''):''}${r.asset_id&&r.case_id?`<span class="meta"> · ${esc(r.asset_id)}</span>`:''}</summary><div class="record-body"><dl>${Object.entries(r).filter(([,v])=>v!==''&&v!=null).map(([k,v])=>`<dt>${esc(k.replace(/_/g,' '))}</dt><dd>${k.endsWith('_at')?esc(time(v)):esc(v)}</dd>`).join('')}</dl></div></details>`).join('')||'<p class="meta">No linked records in this export.</p>';}
function manifestsView(manifests){return manifests.map(m=>`<details class="record"><summary><strong>${esc(m.kind)}</strong> · ${esc(m.filename)} · ${nf(m.rows)} rows</summary><div class="record-body"><p class="meta">Original file SHA-256</p><p class="mono">${esc(m.sha256)}</p><p class="meta spaced">Source columns</p><p class="mono">${esc(m.headers.join(', '))}</p></div></details>`).join('');}
function policyView(p){return `<dl>${Object.entries(p).map(([k,v])=>`<dt>${esc(k.replace(/_/g,' '))}</dt><dd>${esc(Array.isArray(v)?v.join(', '):v)}</dd>`).join('')}</dl>`;}
function dialog(title,subtitle,body,small=false){return `<dialog id="modal" class="${small?'dialog-small':''}" aria-labelledby="dialog-title"><div class="dialog-head"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${btn(icon('close'),'close-modal','quiet','aria-label="Close dialog"')}</div><div class="dialog-body">${body}</div></dialog>`;}
function investigationView(f,back){
 const i=f.investigation,peer=i.peer,ev=f.evidence,recordChecks=f.record_explanations||[];
 const escalation=f.detector==='missing_escalation';
 const own=escalation&&peer.entity_rate!==null?100-peer.entity_rate:peer.entity_rate;
 const baseline=escalation&&peer.peer_median!==null?100-peer.peer_median:peer.peer_median;
 const metric=escalation?'Eligible cases with recorded escalation':'Affected records';
 return `${back?btn('Back to selected record','back-modal','quiet'):''}<div class="investigation-grid"><section class="investigation-block"><h3>Policy / expected evidence</h3><p>${esc(recordChecks[0]?.expected||f.rationale)}</p><p class="meta">${esc(f.rationale)}</p></section><section class="investigation-block"><h3>Peer baseline · ${esc(metric)}</h3><strong>${percent(own)} here · ${percent(baseline)} peer median</strong><p class="meta">${peer.eligible_peers} eligible peers; minimum 2. ${baseline===null?'Comparison unavailable for this metric.':''}</p><details><summary>Cohort criteria</summary><p class="field-help">${esc(i.peer_criteria)}</p></details><p class="field-help">Recorded escalation presence is not verified policy compliance.</p></section></div><h3 class="spaced">Why these records were flagged</h3><div class="table-wrap"><table><thead><tr><th>Source ID / asset</th><th>Effective severity</th><th>Closed (UTC)</th><th>${ev.kind==='assets'?'Coverage records':'Escalation records'}</th><th>Evidence</th></tr></thead><tbody>${i.rows.map(r=>`<tr><td class="mono">${esc(r.record_id)}<span class="subline">${esc(r.asset_id||'Not supplied')}</span></td><td>${badge(r.severity,r.severity==='critical'?'high':'')}</td><td>${r.closed_at?esc(r.closed_at):'Not in primary record'}</td><td>${ev.kind==='assets'?nf(r.coverage_count):r.escalation_count?nf(r.escalation_count):'Absent in export'}</td><td>${btn('Open record','open-record','',`data-submission="${esc(f.submission_id)}" data-kind="${esc(r.kind)}" data-id="${esc(r.record_id)}"`)}</td></tr>`).join('')}</tbody></table></div><div class="pager">${btn('Previous records','evidence-page','',`data-offset="${Math.max(0,ev.offset-ev.limit)}" ${ev.offset===0?'disabled':''}`)}<span>${ev.total?ev.offset+1:0}–${Math.min(ev.offset+ev.limit,ev.total)} of ${nf(ev.total)}</span>${btn('Next records','evidence-page','',`data-offset="${ev.offset+ev.limit}" ${ev.offset+ev.limit>=ev.total?'disabled':''}`)}</div><section class="investigation-block"><h3>Detection logic & traceability</h3><dl><dt>Stored detector</dt><dd class="mono">${esc(f.detector)} v${esc(f.detector_version)}</dd><dt>Required input files present</dt><dd>${i.input_presence_percent}% · ${i.supplied_inputs.length}/${i.required_inputs.length}: ${i.supplied_inputs.map(esc).join(', ')}</dd><dt>Source export completeness</dt><dd>Unverified — input presence does not establish export completeness.</dd><dt>Submission SHA-256</dt><dd class="mono">${esc(i.checksum)}</dd></dl>${Object.keys(f.context||{}).length?`<details class="spaced"><summary>Measured detector context</summary>${recordsView([f.context],'context')}</details>`:''}</section><div class="notice warning spaced">${icon('info')}<div>${f.limitations.map(esc).join(' ')}<p>${esc(recordChecks[0]?.examiner_check||'Confirm the records and policy with the entity.')}</p></div></div><div class="actions spaced">${writable()?btn('Accept finding','decision-intent','primary','data-status="confirmed"')+btn('Dismiss','decision-intent','','data-status="dismissed"')+btn('Needs information','decision-intent','','data-status="clarification"'):''}${btn('Full record checks','finding-tab','','data-tab="explanation"')}</div><p class="footnote">A decision applies to the finding group and requires a written reason. Previous decisions remain in the audit history.</p>`;
}
function independentSampleView(data){return `<div class="notice">${icon('review')}<div><strong>Check what the detectors missed</strong><p>${esc(data.purpose)}</p>${esc(data.method)}<p class="meta">Stored engine ${esc(data.engine_version)} · ${nf(data.population)} eligible cases of ${nf(data.period_cases)} in-period cases; ${nf(data.excluded_cases)} excluded.</p></div></div><div class="selected-list">${data.records.map(c=>{const o=data.observations.find(o=>o.case_id===c.case_id);return `<article class="selected-record"><div class="sample-main"><h3 class="mono">${esc(c.case_id)}</h3><p>${o?esc(o.status.replaceAll('_',' '))+' · '+esc(o.actor):'Awaiting independent human review'}</p>${o?`<p class="meta">${esc(o.comment)}</p>`:''}</div><div class="actions">${btn('Open full evidence','open-record','',`data-submission="${esc(data.submission_id)}" data-kind="cases" data-id="${esc(c.case_id)}"`)}${writable()?btn('Record observation','observe-sample','',`data-id="${esc(c.case_id)}"`):''}</div></article>`;}).join('')||empty('No eligible unflagged cases','All in-period cases are associated with a stored finding or no case export was supplied.')}</div><p class="footnote">Concerns do not automatically become confirmed findings or change the stored index.</p>`;}
function sampleObservationView(m){const latest=m.sample.observations.find(o=>o.case_id===m.caseId);return `${btn('Back to independent sample','back-modal','quiet')}<form id="sample-observation-form" class="spaced"><label>Independent examiner observation<select name="status">${[['no_concern','No concern observed'],['concern','Concern requiring adjudication'],['needs_info','Needs more information']].map(([id,label])=>option(id,label,latest?.status||'needs_info')).join('')}</select></label><label class="spaced">Evidence checked and reasoning<textarea name="comment" required minlength="5" maxlength="4000">${esc(latest?.comment||'')}</textarea></label><p class="field-help">A concern is a potential false negative requiring expert adjudication. This does not change automated findings or the stored attention index.</p><div class="button-row"><button class="primary" type="submit">Save observation</button></div></form><h3 class="spaced">Observation history</h3>${m.sample.observations.filter(o=>o.case_id===m.caseId).map(o=>`<div class="history"><strong>${esc(o.status.replaceAll('_',' '))}</strong><p>${esc(o.comment)}</p><p class="meta">${esc(o.actor)} · ${esc(time(o.created_at))} · version ${o.version}</p></div>`).join('')||'<p class="meta">No previous observations.</p>'}`;}
function renderModal(){
 if(S.modal?.type==='reanalyse')return dialog('Re-analyse stored submission','Creates a separate assessment under the running engine. Existing findings and examiner decisions remain in their original assessment.',`<form id="reanalyse-form"><label>Reason<textarea name="reason" required minlength="5" maxlength="4000" placeholder="Explain why this assessment needs re-analysis."></textarea></label><div class="button-row"><button type="submit" class="primary">Create new assessment</button></div></form>`,true);
 const m=S.modal;if(!m)return '';
 if(m.type==='recommended')return dialog('Recommended examiner sample',`${esc(shortName(m.submission.entity_name))} · ${m.data.selected_count} selected records`, `<div class="notice">${icon('review')}<div>${esc(m.data.method)}</div></div><div class="selected-list">${selectionCards(m.data,m.submission.id)}</div><p class="footnote">${esc(m.data.limitation)}</p>`);
 if(m.type==='record'){
  const r=m.data, selected=m.selection, tab=m.tab||'explanation';
  let body=`<div class="finding-summary"><div class="tags">${badge(r.kind,'kind')}${badge(r.effective_severity,r.effective_severity==='critical'?'high':'')}${badge(`${r.signals.length} associated signals`)}</div><strong class="mono">${esc(r.record_id)}</strong>${selected?`<p>${esc(selected.selection_reason)}</p><p class="meta">Sample position ${selected.rank} · ${selected.score} review points = severity ${selected.score_breakdown.severity} + signal priority ${selected.score_breakdown.highest_signal_priority} + additional detectors ${selected.score_breakdown.additional_detectors}. Not a risk probability.</p>`:''}<p class="meta">${date(r.period_start)} to ${date(r.period_end)} (end exclusive) · ${esc(r.submission_id)}</p></div><div class="actions spaced">${m.back?btn('Back to evidence list','back-modal','quiet'):S.assessment?btn('Back to recommended sample','back-recommended','quiet'):''}</div><div class="tabs" role="tablist" aria-label="Record details">${[['explanation','Why selected'],['records','Full records'],['provenance','Source & policy']].map(([id,label])=>btn(label,'finding-tab',tab===id?'active':'',`data-tab="${id}" role="tab" aria-selected="${tab===id}"`)).join('')}</div>`;
  if(tab==='explanation'){
   body+=r.signals.map(signal=>`<section class="record-signal"><div class="split"><div><div class="tags">${badge(signal.kind,'kind')}${badge(signal.status,signal.status)}</div><h3>${esc(signal.title)}</h3></div>${btn('Review finding group','finding','',`data-id="${esc(signal.id)}"`)}</div><p class="meta">Decision applies to this finding group. ${esc(signal.comment||'Awaiting examiner judgement.')}</p>${signal.explanations.map(explanationView).join('')}<p class="footnote">${signal.explanations_total>20?`Showing 20 of ${signal.explanations_total} associated record checks; open the finding group for paginated evidence. `:''}${signal.limitations.map(esc).join(' ')}</p></section>`).join('')||'<p class="muted">No automated finding references this record.</p>';
   body+=`<h3 class="spaced">Operational timeline</h3><ol class="evidence-timeline">${r.timeline.map(event=>`<li><span class="timeline-dot"></span><div><strong>${esc(event.event)}</strong><span class="subline">${esc(time(event.at))}</span><small class="mono">${esc(event.record_id)}</small></div></li>`).join('')||'<li>No submitted timestamped workflow events for this record.</li>'}</ol>${r.timeline_total>100?`<p class="footnote">First 100 of ${nf(r.timeline_total)} timeline events shown.</p>`:''}`;
   if(r.missing_referenced_cases.length)body+=`<div class="notice warning">${icon('info')}<div><strong>Referenced case evidence absent:</strong> ${r.missing_referenced_cases.map(esc).join(', ')}. Request the source records or confirm the export scope.</div></div>`;
  }else if(tab==='records'){
   body+=`<h3>Selected ${esc(r.kind)} record</h3>${recordsView([r.record],r.kind)}${Object.entries(r.linked).map(([kind,records])=>`<div class="linked"><h3>Submitted ${esc(kind)} (${nf(r.linked_totals[kind])})</h3>${recordsView(records,kind)}${r.linked_totals[kind]>100?'<p class="footnote">First 100 linked records shown. The source export retains all records.</p>':''}</div>`).join('')}`;
  }else{
   body+=`<h3>Traceable source record</h3><dl class="spaced"><dt>Source file</dt><dd>${esc(r.source?.filename||'Unavailable')}</dd><dt>File SHA-256</dt><dd class="mono">${esc(r.source?.sha256||'Unavailable')}</dd><dt>Normalised record number</dt><dd>${r.normalised_record_number} (position in the parsed dataset; not a physical CSV line)</dd><dt>Submission SHA-256</dt><dd class="mono">${esc(r.checksum)}</dd><dt>Stored rule engine</dt><dd>${esc(r.engine_version)}</dd></dl><details class="record spaced"><summary>Preserved policy</summary><div class="record-body">${policyView(r.policy)}</div></details><div class="spaced">${manifestsView(r.manifests)}</div>`;
  }
  return dialog('Record evidence & explanation',esc(shortName(r.entity_name)),body);
 }
 if(m.type==='finding'){
  const f=m.data, ev=f.evidence, tab=m.tab||'investigation';
  let body=`<div class="finding-summary"><div class="tags">${badge(f.priority,f.priority)}${badge(f.kind,'kind')}${badge(f.status,f.status)}</div><strong>${esc(f.summary)}</strong><p>${esc(f.rationale)}</p><p class="meta">${esc(f.domain)} · ${nf(f.affected_count)} / ${nf(f.denominator)} ${esc(f.unit)} · Rule ${esc(f.detector)} v${esc(f.detector_version)}</p></div><div class="tabs" role="tablist" aria-label="Finding details">${[['investigation','Evidence Investigation'],['explanation','Why flagged'],['evidence','Evidence'],['review','Examiner decision'],['provenance','Provenance']].map(([id,title])=>btn(title,'finding-tab',tab===id?'active':'',`data-tab="${id}" role="tab" aria-selected="${tab===id}"`)).join('')}</div>`;
  if(tab==='investigation'){body+=investigationView(f,m.back);}else if(tab==='explanation'){body+=`${m.back?btn('Back to selected record','back-modal','quiet'):''}<p class="field-help">Record-specific checks for this page of supporting evidence. Missing submitted evidence must be confirmed with the entity.</p>${(f.record_explanations||[]).map(explanationView).join('')}<div class="pager">${btn('Previous records','evidence-page','',`data-offset="${Math.max(0,ev.offset-ev.limit)}" ${ev.offset===0?'disabled':''}`)}<span>${ev.total?ev.offset+1:0}–${Math.min(ev.offset+ev.limit,ev.total)} of ${nf(ev.total)}</span>${btn('Next records','evidence-page','',`data-offset="${ev.offset+ev.limit}" ${ev.offset+ev.limit>=ev.total?'disabled':''}`)}</div>`;}else if(tab==='evidence'){
   body+=`<div class="pager"><strong>Supporting ${esc(ev.kind)} · ${nf(ev.total)} records</strong><span>Showing ${ev.total?ev.offset+1:0}–${Math.min(ev.offset+ev.limit,ev.total)}</span></div>${recordsView(ev.records,ev.kind)}<div class="pager">${btn('Previous records','evidence-page','',`data-offset="${Math.max(0,ev.offset-ev.limit)}" ${ev.offset===0?'disabled':''}`)}${btn('Next records','evidence-page','',`data-offset="${ev.offset+ev.limit}" ${ev.offset+ev.limit>=ev.total?'disabled':''}`)}</div><div class="linked"><h3>Linked alert evidence (${ev.linked_alerts.length}${ev.linked_alerts.length===200?'; limited to first 200':''})</h3>${recordsView(ev.linked_alerts,'alerts')}</div>${ev.kind!=='cases'?`<div class="linked"><h3>Linked cases (${ev.linked_cases.length})</h3>${recordsView(ev.linked_cases,'cases')}</div>`:''}<div class="linked"><h3>Linked escalation records (${ev.linked_escalations.length})</h3>${recordsView(ev.linked_escalations,'escalations')}</div>${ev.linked_assets?.length?`<div class="linked"><h3>Asset inventory</h3>${recordsView(ev.linked_assets,'assets')}</div>`:''}${ev.kind==='assets'?`<div class="linked"><h3>Source coverage records (${ev.linked_coverage.length})</h3>${recordsView(ev.linked_coverage,'coverage')}</div>`:''}<div class="notice warning spaced">${icon('info')}<div>${f.limitations.map(esc).join(' ')}</div></div>`;
  }else if(tab==='review'){
   body+=writable()?`<form id="review-form"><label>Examiner decision<select name="status">${[['pending','Pending review'],['confirmed','Confirm finding'],['dismissed','Dismiss finding'],['clarification','Request clarification']].map(([id,label])=>option(id,label,m.intent||f.status)).join('')}</select></label><label class="spaced">Reason and follow-up<textarea name="comment" required minlength="5" maxlength="4000" placeholder="Record the evidence checked, your interpretation and any follow-up required.">${esc(f.comment)}</textarea></label><p class="field-help">Every saved decision preserves the examiner, timestamp and previous review history.</p><div class="button-row"><button class="primary" type="submit">Save examiner decision</button></div></form>`:'<div class="notice">Your account has read-only access.</div>';
   body+=`<h3 class="spaced">Review history</h3>${f.reviews.map(r=>`<div class="history">${badge(r.status,r.status)}<span class="meta"> ${esc(r.actor)} · ${esc(time(r.created_at))}</span><p>${esc(r.comment)}</p></div>`).join('')||'<p class="meta spaced">No examiner decisions recorded yet.</p>'}`;
  }else{
   body+=`<h3>Source submission</h3><p class="mono">${esc(f.submission_id)} · ${esc(f.id)}</p><p class="meta">${date(f.period_start)} to ${date(f.period_end)} (end exclusive)</p><div class="spaced">${manifestsView(f.manifests)}</div><details class="record"><summary>Preserved assessment policy</summary><div class="record-body">${policyView(f.policy)}</div></details><p class="footnote">Source identifiers are retained. Original exports and normalised records are stored locally. Changes to an entity policy do not alter an existing assessment.</p>`;
  }
  return dialog(esc(f.title),esc(shortName(f.entity_name)),body);
 }
 if(m.type==='entity')return dialog('Register entity','Set the context for periodic SOC assessments.',`<form id="entity-form"><label>Entity name<input name="name" required minlength="2" maxlength="100" placeholder="Organisation name"></label><label class="spaced">Sector<input name="sector" required maxlength="80" placeholder="Energy, Banking, Telecom…"></label><label class="spaced">Size band<select name="size_band"><option value="small">Small</option><option value="medium" selected>Medium</option><option value="large">Large</option></select></label><div class="button-row"><button class="primary" type="submit">Register entity</button></div></form>`,true);
 if(m.type==='policy'){
  const e=m.entity,p=e.policy;
  return dialog('Entity assessment policy',esc(shortName(e.name)),`<form id="policy-form"><div class="form-grid"><label>Fast closure threshold (minutes)<input name="fast_closure_minutes" type="number" min="0.1" max="120" step="0.1" value="${p.fast_closure_minutes}" required></label><label>Acknowledgement SLA (minutes)<input name="acknowledgement_sla_minutes" type="number" min="1" max="1440" value="${p.acknowledgement_sla_minutes??30}" required></label><label>Coverage freshness (hours)<input name="coverage_stale_hours" type="number" min="1" max="8760" value="${p.coverage_stale_hours}" required></label><label>Recurring alert minimum<input name="repeated_alert_minimum" type="number" min="2" max="1000" value="${p.repeated_alert_minimum}" required></label><label>Repeated narrative minimum<input name="repeated_note_minimum" type="number" min="2" max="1000" value="${p.repeated_note_minimum}" required></label></div><label class="spaced">Escalation required for<select name="escalation_severities"><option value="critical" ${p.escalation_severities.join(',')==='critical'?'selected':''}>Critical</option><option value="critical,high" ${p.escalation_severities.includes('high')?'selected':''}>Critical and high</option><option value="" ${!p.escalation_severities.length?'selected':''}>None (no escalation requirement)</option></select></label><div class="notice warning spaced">${icon('info')}<div>Use the entity's documented policy. This changes future assessments; previous results retain their policy snapshot.</div></div><div class="button-row"><button class="primary" type="submit">Save policy</button></div></form>`);
 }
 if(m.type==='submission'){
  const s=m.data;
  return dialog('Assessment provenance',esc(shortName(s.entity_name)),`${assessmentScope(s)}<p class="meta">Created ${time(s.created_at)} · ${esc(s.id)}</p><p class="mono spaced">Submission SHA-256: ${esc(s.checksum)}</p><h3 class="spaced">Source manifests</h3><div class="spaced">${manifestsView(s.validation.manifests)}</div><details class="record"><summary>Preserved policy</summary><div class="record-body">${policyView(s.policy)}</div></details><h3 class="spaced">Validation notes</h3><div class="issue-list">${s.validation.issues.map(i=>`<div class="issue ${i.level}">${esc(i.file)}: ${esc(i.message)}</div>`).join('')||'<p class="meta">No structural issues found.</p>'}</div><div class="button-row">${btn('Export this assessment','report','primary',`data-format="json" data-submission="${esc(s.id)}"`)}</div>`);
 }
 if(m.type==='sample')return dialog('Independent case sample',esc(m.name),independentSampleView(m.data));
 if(m.type==='sample-observation')return dialog('Independent review observation',esc(m.caseId),sampleObservationView(m));
 if(m.type==='evaluation')return dialog('Expert comparison result',esc(m.data.id),evaluationView(m.data));
 if(m.type==='audit')return dialog('Assessment audit history',`${m.data.verification.checked} chain records checked`, `<div class="notice ${m.data.verification.valid?'success':'warning'}">${icon('shield')}<div>Chain ${m.data.verification.valid?'verified':'verification failed'}. ${esc(m.data.verification.limitation||'Check the local database.')}</div></div><div class="table-wrap"><table><thead><tr><th>Time / actor</th><th>Action</th><th>Detail</th></tr></thead><tbody>${m.data.records.map(r=>`<tr><td>${esc(time(r.created_at))}<span class="subline">${esc(r.actor)}</span></td><td class="mono">${esc(r.action)}</td><td class="mono">${esc(JSON.stringify(r.detail))}</td></tr>`).join('')}</tbody></table></div><p class="footnote">Showing the most recent 200 events. Hash verification covers the full stored chain.</p>`);
 if(m.type==='user')return dialog('Create local account','Credentials are stored only on this server.',`<form id="user-form"><label>Username<input name="username" required minlength="3" maxlength="60" autocomplete="off"></label><label class="spaced">Password<input name="password" type="password" required minlength="10" maxlength="512" autocomplete="new-password"></label><label class="spaced">Role<select name="role"><option value="reader">Reader — inspect and export</option><option value="examiner">Examiner — import and review</option></select></label><div class="button-row"><button class="primary" type="submit">Create account</button></div></form>`,true);
 return '';
}

async function loadBundle(file){if(!file)return;try{if(file.size>S.runtime.max_body_bytes)throw new Error('Bundle exceeds this deployment’s upload limit.');const bundle=JSON.parse(await file.text());if(!bundle.files||typeof bundle.files!=='object')throw new Error('Use a SAT-SA periodic export bundle.');const files={};for(const [kind,f] of Object.entries(bundle.files)){if(!S.data.schemas[kind]||typeof f.content!=='string')throw new Error('Unknown dataset or invalid content.');files[kind]={...f,headers:fileHeaders(f.content,f.filename||kind+'.json'),mapping:f.mapping||{}};}S.import.files=files;S.import.start=bundle.period_start.slice(0,10);S.import.end=bundle.period_end.slice(0,10);S.import.validation=null;render();toast('Bundle loaded. Validate before assessment.');}catch(e){toast(e.message,true);}}
async function loadExpertLabels(file){if(!file)return;operation(async()=>{if(file.size>12*1024*1024)throw new Error('Label file exceeds 12 MiB.');const result=await api('/submissions/'+S.assessment.submission.id+'/evaluate',{filename:file.name,content:await file.text(),budget:8});S.modal={type:'evaluation',data:result};toast('Expert comparison saved with label hash and audit entry.');});}
function evaluationView(r){return `<div class="notice"><div>${esc(r.label_source)}<p>${r.labelled_records} adjudicated held-out records. Precision ${r.precision===null?'N/A':percent(r.precision*100)}; recall ${r.recall===null?'N/A':percent(r.recall*100)}.</p></div></div><h3 class="spaced">Record-level comparison</h3>${recordsView([r.confusion],'confusion')}<h3 class="spaced">Review budget ${r.review_budget}</h3><p>Prioritised: ${r.prioritised_review.concerns_found} concerns among ${r.prioritised_review.reviewed} records. Seeded baseline: ${r.hash_baseline_review.concerns_found} among ${r.hash_baseline_review.reviewed}.</p><p class="mono spaced">Labels SHA-256 ${esc(r.label_sha256)}</p><ul class="spaced">${r.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="footnote">Full comparison, scope and selected IDs are included in JSON assessment reports.</p>`;}
async function loadFile(kind,file){if(!file)return;if(file.size>12*1024*1024)return toast('Each selected file must be below 12 MiB.',true);if(!/\.(csv|json)$/i.test(file.name))return toast('Select a CSV or JSON file.',true);try{const content=await file.text();const headers=fileHeaders(content,file.name);S.import.files[kind]={filename:file.name,format:file.name.toLowerCase().endsWith('.json')?'json':'csv',content,headers,mapping:{}};S.import.validation=null;render();}catch(error){toast('Unable to read the file: '+error.message,true);}}
function importPayload(){return {entity_id:S.import.entity,period_start:S.import.start+'T00:00:00Z',period_end:S.import.end+'T00:00:00Z',files:Object.fromEntries(Object.entries(S.import.files).map(([k,f])=>[k,{filename:f.filename,format:f.format,content:f.content,mapping:f.mapping}]))};}
async function downloadReport(format,submission){const params=new URLSearchParams({format});if(submission)params.set('submission_id',submission);else if(S.reportEntity)params.set('entity_id',S.reportEntity);const response=await fetch('/api/report?'+params,{credentials:'same-origin'});if(!response.ok){const data=await response.json();throw new Error(data.error||'Export failed.');}const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='SENTRA-AI-assessment.'+format;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Assessment report downloaded.');}
document.addEventListener('click',event=>{
 const button=event.target.closest('button[data-act]');if(!button||button.disabled)return;
 const act=button.dataset.act;
 const sampleId=act==='sample'?$('sample-submission')?.value:null;
 if(act==='nav'){S.page=button.dataset.page;S.modal=null;render();window.scrollTo(0,0);return;}
 if(act==='clear-filters'){S.filter={search:'',entity:'',kind:'',status:''};render();return;}
 if(act==='reset-scope'){S.period='latest';S.filter={search:'',entity:'',kind:'',status:''};render();return;}
 if(act==='all-statuses'){S.page='findings';S.filter.search='';S.filter.kind='';S.filter.status='';render();return;}
 if(act==='assessment-findings'){S.period='assessment:'+S.assessment.submission.id;S.filter={search:'',entity:S.assessment.submission.entity_id,kind:'',status:''};S.page='findings';S.modal=null;render();window.scrollTo(0,0);return;}
 if(act==='recommended'){S.modal={type:'recommended',data:S.assessment.selection,submission:S.assessment.submission};render();return;}
 if(act==='back-modal'){S.modal=S.modal.back;render();return;}
 if(act==='back-recommended'){S.modal={type:'recommended',data:S.assessment.selection,submission:S.assessment.submission};render();return;}
 if(act==='close-modal'){S.modal=null;render();return;}
 if(act==='new-entity'){S.modal={type:'entity'};render();return;}
 if(act==='new-user'){S.modal={type:'user'};render();return;}
 if(act==='reanalyse'){S.modal={type:'reanalyse',submissionId:S.assessment.submission.id};render();return;}
 if(act==='entity-findings'){if(S.period.startsWith('assessment:')&&submissions()[0]?.entity_id!==button.dataset.id)S.period='latest';S.page='findings';S.filter={search:'',entity:button.dataset.id,kind:'',status:''};render();window.scrollTo(0,0);return;}
 if(act==='policy'){S.modal={type:'policy',entity:S.data.entities.find(e=>e.id===button.dataset.id)};render();return;}
 if(act==='decision-intent'){S.modal.tab='review';S.modal.intent=button.dataset.status;render();return;}
 if(act==='finding-tab'){S.modal.tab=button.dataset.tab;render();return;}
 if(act==='remove-file'){delete S.import.files[button.dataset.kind];S.import.validation=null;render();return;}
 operation(async()=>{
  if(act==='logout'){await api('/auth/logout',{});S.user=null;S.data=null;S.modal=null;S.error='';}
  else if(act==='load-demo'){const result=await api('/demo/load',{});await refresh();toast(result.message);S.page='overview';}
  else if(act==='finding'){S.modal={type:'finding',data:await api('/findings/'+button.dataset.id),tab:'investigation',back:S.modal?.type==='record'?S.modal:null};}
  else if(act==='evidence-page'){S.modal.data=await api('/findings/'+S.modal.data.id+'?offset='+button.dataset.offset);}
  else if(act==='assessment'){S.assessment=await api('/submissions/'+button.dataset.id+'/assessment');S.page='assessment';S.modal=null;window.scrollTo(0,0);}
  else if(act==='open-record'){const plan=S.modal?.type==='recommended'?S.modal.data:S.assessment?.selection;const submission=button.dataset.submission;const selection=plan?.records.find(r=>r.kind===button.dataset.kind&&r.record_id===button.dataset.id);const back=['sample','finding'].includes(S.modal?.type)?S.modal:null;S.modal={type:'record',data:await api('/submissions/'+submission+'/record?'+new URLSearchParams({kind:button.dataset.kind,id:button.dataset.id})),selection:back?null:selection,plan,back};}
  else if(act==='observe-sample'){S.modal={type:'sample-observation',caseId:button.dataset.id,sample:S.modal.data,name:S.modal.name,back:S.modal};}
  else if(act==='submission'){S.modal={type:'submission',data:await api('/submissions/'+button.dataset.id)};}
  else if(act==='validate'){S.import.validation=await api('/import/validate',importPayload());toast(S.import.validation.valid?'Validation passed. Ready to assess.':'Correct the validation errors before assessment.',!S.import.validation.valid);}
  else if(act==='run-assessment'){if(S.data.application_version!==CLIENT_VERSION)throw new Error('The server is running a different release. Restart the updated application before assessing these files.');try{const result=await api('/import/run',importPayload());await openAssessmentResult(result);S.import.files={};S.import.validation=null;toast(`${result.findings} finding groups created from ${nf(result.rows)} source records. Opened assessment ${result.id}.`);}catch(error){if(error.status===409&&error.details?.submission_id){await openAssessmentResult({id:error.details.submission_id});toast('Opened the existing assessment for this exact upload.');return;}if(error.details?.issues)S.import.validation=error.details;throw error;}}
  else if(act==='blind-review'){const response=await fetch('/api/submissions/'+button.dataset.submission+'/blind-review',{credentials:'same-origin'});if(!response.ok)throw new Error('Review package unavailable.');const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download='SAT-SA-blinded-review.zip';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Blinded review package downloaded.');}
  else if(act==='report'){await downloadReport(button.dataset.format,button.dataset.submission);}
  else if(act==='audit'){S.modal={type:'audit',data:await api('/audit')};}
  else if(act==='assessment-sample'){S.modal={type:'sample',name:shortName(S.assessment.submission.entity_name),data:await api('/submissions/'+S.assessment.submission.id+'/sample')};}
  else if(act==='sample'){const id=sampleId,s=S.data.submissions.find(x=>x.id===id);S.modal={type:'sample',name:shortName(s.entity_name),data:await api('/submissions/'+id+'/sample')};}
 });
});
document.addEventListener('submit',event=>{
 const form=event.target;if(!['login-form','entity-form','review-form','policy-form','user-form','sample-observation-form','reanalyse-form'].includes(form.id))return;event.preventDefault();
 const values=Object.fromEntries(new FormData(form));
 operation(async()=>{
  if(form.id==='login-form'){try{S.user=await api('/auth/login',values);S.error='';await refresh();}catch(error){S.error=error.message;throw error;}}
  else if(form.id==='entity-form'){const result=await api('/entities',values);S.import.entity=result.id;S.import.validation=null;await refresh();S.modal=null;toast('Entity registered. Import its SOC exports to begin.');}
  else if(form.id==='reanalyse-form'){try{const result=await api('/submissions/'+S.modal.submissionId+'/reanalyse',values);await openAssessmentResult(result);toast('New assessment created; original history preserved.');}catch(error){if(error.status===409&&error.details?.submission_id){await openAssessmentResult({id:error.details.submission_id});toast('This engine has already assessed the same files and policy. Opened that assessment.');}else throw error;}}
  else if(form.id==='review-form'){const id=S.modal.data.id;await api('/findings/'+id+'/review',{...values,version:S.modal.data.version});await refresh();S.modal={type:'finding',data:await api('/findings/'+id),tab:'review',back:S.modal.back?{...S.modal.back,data:await api('/submissions/'+S.modal.back.data.submission_id+'/record?'+new URLSearchParams({kind:S.modal.back.data.kind,id:S.modal.back.data.record_id}))}:null};toast('Examiner decision saved.');}
  else if(form.id==='sample-observation-form'){const m=S.modal,latest=m.sample.observations.find(o=>o.case_id===m.caseId);await api('/submissions/'+m.sample.submission_id+'/sample-observation',{...values,case_id:m.caseId,version:latest?.version||0});await refresh();S.modal={type:'sample',name:m.name,data:await api('/submissions/'+m.sample.submission_id+'/sample')};toast('Independent review observation saved and audited.');}
  else if(form.id==='policy-form'){const data={};for(const [k,v] of Object.entries(values))data[k]=k==='escalation_severities'?(v?v.split(','):[]):Number(v);await api('/entities/'+S.modal.entity.id+'/policy',data);await refresh();S.modal=null;S.import.validation=null;toast('Policy saved for future assessments.');}
  else if(form.id==='user-form'){await api('/users',values);S.modal=null;toast('Local account created. Share its credentials through your approved process.');}
 });
});
document.addEventListener('change',event=>{
 const el=event.target,id=el.id;
 if(id==='bundle-file'){loadBundle(el.files[0]);return;}
 if(id==='expert-label-file'){loadExpertLabels(el.files[0]);return;}
 if(el.dataset.file){loadFile(el.dataset.file,el.files[0]);return;}
 if(el.dataset.mapKind){S.import.files[el.dataset.mapKind].mapping[el.dataset.mapField]=el.value;S.import.validation=null;render();return;}
 if(id==='period-select'){S.period=el.value;render();}
 else if(id==='finding-entity'){S.filter.entity=el.value;render();}
 else if(id==='finding-kind'){S.filter.kind=el.value;render();}
 else if(id==='finding-status'){S.filter.status=el.value;render();}
 else if(id==='report-entity'){S.reportEntity=el.value;}
 else if(id==='import-entity'){S.import.entity=el.value;S.import.validation=null;render();}
 else if(id==='import-start'||id==='import-end'){S.import[id==='import-start'?'start':'end']=el.value;S.import.validation=null;render();}
});
document.addEventListener('input',event=>{if(event.target.id==='finding-search'){S.filter.search=event.target.value;render();}});
document.addEventListener('dragover',event=>{if(event.target.closest('[data-drop]'))event.preventDefault();});
document.addEventListener('drop',event=>{const card=event.target.closest('[data-drop]');if(!card||!writable())return;event.preventDefault();loadFile(card.dataset.drop,event.dataTransfer.files[0]);});
async function boot(){render();try{S.runtime=await api('/health');S.runtime.max_body_bytes=S.runtime.max_body_bytes||24*1024*1024;S.user=await api('/auth/me');await refresh();}catch(error){if(error.status!==401)S.error=error.message;S.user=null;}render();}
boot();
